content = open('css/style.css', 'r', encoding='utf-8').read()
import re
content = re.sub(r'/\* =========================================\s*FAX PRINTER OVERLAY.*?$', '', content, flags=re.DOTALL)
new_css = '''
/* =========================================\n   FOOTER NOTH.IN STYLE\n   ========================================= */\n\n.section--footer {\n  position: relative;\n  width: 100%;\n  background: #fff;\n  color: #111;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  padding: 4cqh 5cqw;\n  min-height: 100vh;\n}\n\n.footer-top {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n}\n\n.footer-top-left, .footer-top-right {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n}\n\n.footer-reveal-container {\n  position: relative;\n  width: 100%;\n  height: 50vh;\n  margin: 5vh 0;\n  overflow: hidden;\n  background-color: #fff;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n}\n\n.giant-rishi {\n  font-family: \'Termina\', sans-serif;\n  font-size: 15vw;\n  line-height: 1;\n  text-align: center;\n  margin: 0;\n  color: #000;\n  position: relative;\n  z-index: 1;\n}\n\n.footer-reveal-video {\n  position: absolute;\n  width: 500px;\n  height: 500px;\n  border-radius: 50%;\n  object-fit: cover;\n  pointer-events: none;\n  opacity: 0;\n  transition: opacity 0.3s ease;\n  transform: translate(-50%, -50%);\n  z-index: 2;\n  mix-blend-mode: screen;\n}\n\n.footer-reveal-container:hover .footer-reveal-video {\n  opacity: 1;\n}\n\n.footer-bottom {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n'''
open('css/style.css', 'w', encoding='utf-8').write(content + new_css)
